-- These strings are interface copy reviewed for Uzbek Latin script. Vocabulary meanings remain absent until separately sourced and verified.
comment on column public.vocabulary.translation_uz is 'Optional Uzbek vocabulary meaning; leave NULL unless sourced and reviewed. Do not mark unverified values as verified.';
comment on column public.vocabulary.example_uz is 'Optional Uzbek example translation; leave NULL unless sourced and reviewed.';
comment on column public.vocabulary.translation_uz_verified is 'Verification status for the Uzbek vocabulary meaning. Defaults to false.';
comment on column public.vocabulary.example_uz_verified is 'Verification status for the Uzbek example translation. Defaults to false.';
